  {
    "id": 28,
    "knowledge": "LogMethod (Registration Method)",
    "description": "Illustrates different scan registration methodologies in archaeological documentation.",
    "definition": "A categorization of alignment techniques with specific methodologies: 'ICP' (Iterative Closest Point algorithm for point cloud alignment), 'Target-based' (alignment using physical reference markers), 'Hybrid' (combination of automatic and manual alignment), and 'SLAM' (Simultaneous Localization and Mapping for real-time registration). Each method has distinct accuracy characteristics and use cases."
  },
  {
    "id": 29,
    "knowledge": "GuessDate (Estimated Dating)",
    "description": "Illustrates dating conventions in archaeological classification for chronological placement.",
    "definition": "Values like '3500-3000 BCE', '1st c. CE', or 'ca. 1450 CE' represent estimated chronological placement based on excavation findings. Precision varies from specific years to century-level estimates depending on available evidence and dating methodologies employed."
  },
  {
    "id": 30,
    "knowledge": "Scan Time Efficiency (STE)",
    "description": "Measures how efficiently scanning time was used relative to data quality and completeness metrics.",
    "definition": "STE = \\frac{SQS \\times \\sqrt{CoverPct}}{SpanMin \\times \\sqrt{ScanCount}}, \\text{ where SQS is the Scan Quality Score and higher STE values indicate more efficient use of scanning time relative to coverage achieved.}"
  },
  {
    "id": 31,
    "knowledge": "Environmental Impact Factor (EIF)",
    "description": "Quantifies how environmental conditions affected scan quality using statistical correlation analysis.",
    "definition": "EIF = \\frac{SQS}{\\text{ESI} + 10} \\times 100, \\text{ where SQS is the Scan Quality Score and ESI is the Environmental Suitability Index. Values closer to 100 indicate minimal environmental interference with data acquisition.}"
  },
  {
    "id": 33,
    "knowledge": "Registration Accuracy Ratio (RAR)",
    "description": "Evaluates registration accuracy relative to scan resolution using propagation of uncertainty principles.",
    "definition": "RAR = \\frac{ScanResolMm}{LogAccuMm \\times \\sqrt{1 + \\frac{ErrValMm}{LogAccuMm}}}, \\text{ where values > 1 indicate registration accuracy exceeds scan resolution, a desirable outcome for precise spatial analysis.}"
  },
  {
    "id": 34,
    "knowledge": "Spatial Density Index (SDI)",
    "description": "Assesses point cloud density relative to site dimensions for spatial sampling adequacy.",
    "definition": "SDI = \\frac{TotalPts}{AreaM2 \\times 10^4} \\times \\left(\\frac{PointDense}{CloudDense}\\right)^{0.5}"
